#ifndef MBEDTLS_ASN1_CHK_CLEANUP_ADD
#define MBEDTLS_ASN1_CHK_CLEANUP_ADD(g, f)                    \
    do {                                                      \
        if ((ret = (f)) < 0)                                  \
            goto cleanup;                                     \
        else                                                  \
            (g) += ret;                                       \
    } while (0)
#endif

