#define MAX_TOKENS 1024

typedef struct {
    const char *json;
    const cj5_token *tokens;
    size_t tokensSize;
    size_t index;
    UA_Byte depth;
    cj5_result result;

    UA_Logger *logging;
} ParsingCtx;

static UA_ByteString
getJsonPart(cj5_token tok, const char *json) {
    UA_ByteString bs;
    UA_ByteString_init(&bs);
    if(tok.type == CJ5_TOKEN_STRING) {
        bs.data = (UA_Byte*)(uintptr_t)(json + tok.start - 1);
        bs.length = (tok.end - tok.start) + 3;
        return bs;
    } else {
        bs.data = (UA_Byte*)(uintptr_t)(json + tok.start);
        bs.length = (tok.end - tok.start) + 1;
        return bs;
    }
}

/* Advances ctx->index and returns the next token, or a zeroed size-0
 * sentinel once the stream is exhausted. A field's declared child count
 * can desync from the actual token count, so this stays in bounds of
 * `tokens[MAX_TOKENS]` even then. */
static cj5_token
nextToken(ParsingCtx *ctx) {
    if(!ctx->tokens || ctx->index + 1 >= ctx->tokensSize) {
        ctx->index = ctx->tokensSize;
        cj5_token empty;
        memset(&empty, 0, sizeof(empty));
        return empty;
    }
    ctx->index++;
    return ctx->tokens[ctx->index];
}

/* Forward declarations*/
#define PARSE_JSON(TYPE) static UA_StatusCode                   \
    TYPE##_parseJson(ParsingCtx *ctx, void *configField, size_t *configFieldSize)

typedef UA_StatusCode
(*parseJsonSignature)(ParsingCtx *ctx, void *configField, size_t *configFieldSize);

