static UA_StatusCode
UA_Sym_EccBrainpoolP384r1_generateKey(const UA_SecurityPolicy *policy,
                                      void *channelContext, const UA_ByteString *secret,
                                      const UA_ByteString *seed, UA_ByteString *out) {
    Policy_Context_EccBrainpoolP384r1 *pctx =
        (Policy_Context_EccBrainpoolP384r1 *)policy->policyContext;
    Channel_Context_EccBrainpoolP384r1 *cc =
        (Channel_Context_EccBrainpoolP384r1 *)channelContext;
    if(!pctx || !cc)
        return UA_STATUSCODE_BADUNEXPECTEDERROR;
    return UA_OpenSSL_ECC_DeriveKeys(OBJ_txt2nid("brainpoolP384r1"), "SHA384",
                                     pctx->applicationType, cc->localEphemeralKeyPair,
                                     secret, seed, out);
}

